// EXPORTS: aiClient
import api from '@/lib/api';
import { scopedStorage, logger } from '@lark-apaas/client-toolkit-lite';

const AI_SECRET_HEADER = { 'X-AI-Secret': 'xh2026ai' };

const CACHE_KEY = 'ai_cache_v1';
const RATE_KEY = 'ai_rate_v1';
const TOKEN_KEY = 'ai_tokens_v1';
const SETTINGS_KEY = 'ai_settings_v1';

const CACHE_TTL_MS = 24 * 60 * 60 * 1000;
const RATE_LIMIT = 5;
const RATE_WINDOW_MS = 60 * 1000;

export interface AISettings {
  autoGenerate: boolean;
}

export interface TokenUsage {
  monthKey: string;
  inputTokens: number;
  outputTokens: number;
  totalTokens: number;
}

interface CacheEntry {
  value: any;
  timestamp: number;
}

function hashQuery(query: string): string {
  // 使用完整 query 计算 hash（之前只取前50字符会导致碰撞）
  const s = query.trim().toLowerCase();
  let h = 0;
  for (let i = 0; i < s.length; i++) {
    h = ((h << 5) - h) + s.charCodeAt(i);
    h |= 0;
  }
  // 加长度后缀避免极端碰撞
  return `${Math.abs(h).toString(36)}_${s.length}`;
}

function getMonthKey(): string {
  const d = new Date();
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
}

function readJSON<T>(key: string, fallback: T): T {
  try {
    const raw = scopedStorage.getItem(key);
    if (raw) return JSON.parse(raw) as T;
  } catch { /* ignore */ }
  return fallback;
}

function writeJSON(key: string, value: unknown) {
  try {
    scopedStorage.setItem(key, JSON.stringify(value));
  } catch { /* ignore */ }
}

export interface GenerateParams {
  productName: string;
  category: string;
  site: string;
  sellingPoints: string;
  imageCount: number;
}

export interface GenerateResult {
  source: 'ai' | 'template' | 'cache';
  amazonTitle?: string;
  tiktokTitle?: string;
  description?: string;
  titles?: string[];
  searchTerms?: string[];
  hashtags?: string[];
  bulletPoints?: Array<{ title: string; desc: string }>;
  storyboard?: Array<{ scene: string; duration: string; visual: string; lines: string; subtitle?: string; bgmTip?: string }>;
  script30s?: { hook: string; intro: string; painPoint: string; callToAction: string };
  script60s?: { hook: string; intro: string; painPoint: string; solution: string; callToAction: string };
  scriptPrompt?: string;
  videoScriptPrompt?: string;
  tokenUsage?: { inputTokens: number; outputTokens: number };
}

export class RateLimitError extends Error {
  constructor(public waitSeconds: number) {
    super(`操作太频繁，请${waitSeconds}秒后再试`);
    this.name = 'RateLimitError';
  }
}

// ---------- 缓存 ----------

function getCache(query: string): any | null {
  const key = hashQuery(query);
  const cache = readJSON<Record<string, CacheEntry>>(CACHE_KEY, {});
  const entry = cache[key];
  if (!entry) return null;
  if (Date.now() - entry.timestamp > CACHE_TTL_MS) {
    delete cache[key];
    writeJSON(CACHE_KEY, cache);
    return null;
  }
  return entry.value;
}

function setCache(query: string, value: any) {
  const key = hashQuery(query);
  const cache = readJSON<Record<string, CacheEntry>>(CACHE_KEY, {});
  cache[key] = { value, timestamp: Date.now() };
  const keys = Object.keys(cache);
  if (keys.length > 50) {
    const sorted = keys.sort((a, b) => cache[a].timestamp - cache[b].timestamp);
    for (let i = 0; i < 10; i++) delete cache[sorted[i]];
  }
  writeJSON(CACHE_KEY, cache);
}

// ---------- 限流 ----------

function checkRateLimit(): { allowed: boolean; waitSeconds?: number } {
  const now = Date.now();
  const record = readJSON<{ timestamps: number[] }>(RATE_KEY, { timestamps: [] });
  const windowStart = now - RATE_WINDOW_MS;
  const filtered = record.timestamps.filter((t) => t > windowStart);

  if (filtered.length >= RATE_LIMIT) {
    const oldest = filtered[0];
    const waitSeconds = Math.ceil((oldest + RATE_WINDOW_MS - now) / 1000);
    return { allowed: false, waitSeconds: Math.max(1, waitSeconds) };
  }
  filtered.push(now);
  writeJSON(RATE_KEY, { timestamps: filtered });
  return { allowed: true };
}

// ---------- Token 统计 ----------

export function getTokenUsage(): TokenUsage {
  const stored = readJSON<TokenUsage | null>(TOKEN_KEY, null);
  const monthKey = getMonthKey();
  if (stored && stored.monthKey === monthKey) return stored;
  return { monthKey, inputTokens: 0, outputTokens: 0, totalTokens: 0 };
}

export function recordTokens(inputTokens: number, outputTokens: number) {
  const monthKey = getMonthKey();
  const stored = readJSON<TokenUsage | null>(TOKEN_KEY, null);
  const base = stored && stored.monthKey === monthKey
    ? stored
    : { monthKey, inputTokens: 0, outputTokens: 0, totalTokens: 0 };
  const next: TokenUsage = {
    monthKey,
    inputTokens: base.inputTokens + inputTokens,
    outputTokens: base.outputTokens + outputTokens,
    totalTokens: base.totalTokens + inputTokens + outputTokens,
  };
  writeJSON(TOKEN_KEY, next);
}

export function formatTokenCount(n: number): string {
  if (n >= 10000) return `${(n / 10000).toFixed(1)}万`;
  if (n >= 1000) return `${(n / 1000).toFixed(1)}k`;
  return String(n);
}

// ---------- 设置 ----------

export function getAISettings(): AISettings {
  return readJSON<AISettings>(SETTINGS_KEY, { autoGenerate: true });
}

export function setAISettings(next: Partial<AISettings>) {
  const prev = getAISettings();
  const merged = { ...prev, ...next };
  writeJSON(SETTINGS_KEY, merged);
  return merged;
}

// ---------- 主调用 ----------

/**
 * 调用 AI 脚本生成接口（带缓存 + 限流 + token 统计）
 * @param params 生成参数
 * @param force 是否强制调用（忽略 autoGenerate 设置，用于手动点"AI生成"）
 * @param fallbackTemplate 本地模板兜底函数，AI 失败/被禁用时调用
 */
export async function generateScript(
  params: GenerateParams,
  force: boolean,
  fallbackTemplate: (p: GenerateParams) => GenerateResult,
): Promise<GenerateResult> {
  const queryStr = `${params.productName}|${params.category}|${params.site}|${params.sellingPoints}|${params.imageCount}`;

  // 1. 先查缓存
  const cached = getCache(queryStr);
  if (cached) {
    logger.info('[ai] 命中缓存');
    return { ...cached, source: 'cache' };
  }

  // 2. 检查设置
  const settings = getAISettings();
  if (!settings.autoGenerate && !force) {
    logger.info('[ai] 自动调用已关闭，使用本地模板');
    const tpl = fallbackTemplate(params);
    return { ...tpl, source: 'template' };
  }

  // 3. 频率限制
  const rate = checkRateLimit();
  if (!rate.allowed) {
    throw new RateLimitError(rate.waitSeconds ?? 60);
  }

    // 4. 真实调用
  try {
    logger.info(`[ai] 调用接口 force=${force} queryLen=${queryStr.length}`);
    const res = await api.post<any>('/generate', params, { timeout: 30000, headers: AI_SECRET_HEADER });
    const data = res?.data;
    if (data && (data.titles || data.amazonTitle || data.tiktokTitle)) {
      // token 统计（后端返回则用后端值，否则估算）
      const inputTokens = data.tokenUsage?.inputTokens ?? estimateInputTokens(params);
      const outputTokens = data.tokenUsage?.outputTokens ?? estimateOutputTokens(data);
      recordTokens(inputTokens, outputTokens);

      const result: GenerateResult = { ...data, tokenUsage: { inputTokens, outputTokens } };
      // 写缓存
      setCache(queryStr, { ...result, tokenUsage: undefined });
      return result;
    }
  } catch (e: any) {
    if (e instanceof RateLimitError) throw e;
    // 后端返回 HTTP 429 也当限流处理
    if (e?.response?.status === 429) {
      const wait = e.response?.data?.retryAfter || 60;
      throw new RateLimitError(wait);
    }
    logger.warn('[ai] 生成失败，降级模板:', String(e));
  }

  // 5. 降级模板
  const tpl = fallbackTemplate(params);
  return { ...tpl, source: 'template' };
}

// 粗略估算 input token（约等于字符数 / 1.5）
function estimateInputTokens(p: GenerateParams): number {
  const totalChars = p.productName.length + p.category.length + p.site.length + p.sellingPoints.length + 200;
  return Math.ceil(totalChars / 1.5);
}

// 粗略估算 output token
function estimateOutputTokens(data: any): number {
  const str = JSON.stringify(data || {});
  return Math.ceil(str.length / 2);
}

/**
 * 通用文本生成（走后端 /ai/text-generate 接口）
 * @param prompt 生成提示词
 * @param options.cacheKey 自定义缓存 key 前缀（相同前缀的相似请求共享缓存）
 * @param options.force 是否强制调用（忽略 autoGenerate 设置）
 * @param options.maxTokens 最大输出 token 数（默认 800）
 * @param options.fallback 失败时的兜底返回
 */
export async function textGenerate(
  prompt: string,
  options: {
    cacheKey?: string;
    force?: boolean;
    maxTokens?: number;
    fallback?: () => string | Promise<string>;
  } = {},
): Promise<{ content: string; source: 'ai' | 'cache' | 'fallback' }> {
  const { cacheKey, force = false, maxTokens = 800, fallback } = options;
  const cacheId = cacheKey || prompt;

  // 1. 查缓存
  const cached = getCache(cacheId);
  if (cached?.content) {
    logger.info('[ai] textGenerate 命中缓存');
    return { content: cached.content, source: 'cache' };
  }

  // 2. 检查设置
  const settings = getAISettings();
  if (!settings.autoGenerate && !force) {
    if (fallback) {
      const content = await fallback();
      return { content, source: 'fallback' };
    }
    throw new Error('AI 自动调用已关闭，请手动触发');
  }

  // 3. 频率限制
  const rate = checkRateLimit();
  if (!rate.allowed) {
    throw new RateLimitError(rate.waitSeconds ?? 60);
  }

  // 4. 调用后端
  try {
    logger.info(`[ai] textGenerate 调用 force=${force} promptLen=${prompt.length} cacheKey=${cacheKey ? 'yes' : 'no'}`);
    const res = await api.post('/ai/text-generate', { prompt, max_tokens: maxTokens }, { timeout: 25000, headers: AI_SECRET_HEADER });
    const content = res?.data?.content || res?.data || '';
    if (content && typeof content === 'string' && content.length > 0) {
      // 估算 token 并记录
      const inputTok = Math.ceil(prompt.length / 1.5);
      const outputTok = Math.ceil(content.length / 2);
      recordTokens(inputTok, outputTok);
      // 写缓存
      setCache(cacheId, { content });
      return { content, source: 'ai' };
    }
  } catch (e: any) {
    if (e instanceof RateLimitError) throw e;
    // 后端返回 HTTP 429 也当限流处理
    if (e?.response?.status === 429) {
      const wait = e.response?.data?.retryAfter || 60;
      throw new RateLimitError(wait);
    }
    logger.warn('[ai] textGenerate 失败:', String(e));
  }

  // 5. 兜底
  if (fallback) {
    const content = await fallback();
    return { content, source: 'fallback' };
  }
  throw new Error('生成失败');
}
